CREATE OR REPLACE FUNCTION public.who_pays(_version uuid DEFAULT NULL,_custom uuid DEFAULT NULL,_client uuid DEFAULT NULL,_launch uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE l client_launches; v uuid:=_version; cp uuid:=_custom; tools boolean:=false; inf boolean:=false; nm text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF _client IS NOT NULL OR _launch IS NOT NULL THEN IF _launch IS NOT NULL THEN SELECT * INTO l FROM client_launches WHERE id=_launch; ELSE SELECT cl.* INTO l FROM client_launches cl JOIN clients c ON c.id=_client WHERE cl.client_id IN(c.id,c.parent_client_id) AND cl.status IN('active','live','on_hold','offboarding') ORDER BY (cl.client_id=c.id) DESC,cl.created_at DESC LIMIT 1; END IF; IF l.id IS NULL THEN RETURN NULL; END IF; IF NOT can_view_client(l.client_id) THEN RAISE EXCEPTION 'Client access required'; END IF; v:=l.plan_version_id; cp:=l.custom_plan_id; ELSE IF NOT is_staff(auth.uid()) AND NOT can_view_commercials(auth.uid()) THEN RAISE EXCEPTION 'Plan access required'; END IF; END IF; IF cp IS NOT NULL THEN SELECT name,includes_reservations_sales_tools INTO nm,tools FROM custom_plans WHERE id=cp; SELECT EXISTS(SELECT 1 FROM custom_plan_services s WHERE s.custom_plan_id=cp AND s.included AND s.pipeline_code='influencer') INTO inf; ELSE SELECT name,includes_reservations_sales_tools INTO nm,tools FROM plan_versions WHERE id=v; SELECT EXISTS(SELECT 1 FROM plan_services s WHERE s.plan_version_id=v AND s.included AND s.pipeline_code='influencer') INTO inf; END IF; IF nm IS NULL THEN RETURN NULL; END IF; RETURN jsonb_build_object('name',nm,'tools_included',tools,'influencer_included',inf,'version',v,'custom',cp); END $$;